const path = require('path');
const uuid = require('uuid/v4');
const getSchema = require('../server/getSchema');
const validateRequest = require('../server/validateRequest');

const pathToFixtures = path.resolve(__dirname, './fixtures');

const complexSchema = getSchema(
  path.resolve(pathToFixtures, 'ComplexRequest.graphql'),
);

const simpleSchema = getSchema(
  path.resolve(pathToFixtures, 'SimpleRequest.graphql'),
);

const validationSchema = getSchema(
  path.resolve(pathToFixtures, 'Validation.graphql'),
);

const arraySchema = getSchema(
  path.resolve(pathToFixtures, 'RequestWithArrays.graphql'),
);

describe('validateRequest', () => {
  it('Should validate that a param has not been passed', () => {
    const errorArray = validateRequest({}, simpleSchema, 'Request');
    expect(errorArray.length === 1).toEqual(true);
  });

  it('Should validate as correct when all params are passed', () => {
    const errorArray = validateRequest(
      { something: uuid() },
      simpleSchema,
      'Request',
    );
    expect(errorArray.length === 0).toEqual(true);
  });

  it('Should validate ids', () => {
    const errorArray = validateRequest(
      { something: false },
      simpleSchema,
      'Request',
    );
    expect(errorArray.length === 1).toEqual(true);
  });

  it('Should validate strings', () => {
    const errorArray = validateRequest(
      { string: 2 },
      validationSchema,
      'Request',
    );
    expect(errorArray.length === 1).toEqual(true);
  });

  it('Should validate ints and floats as numbers', () => {
    const errorArray = validateRequest(
      { int: 'Hello' },
      validationSchema,
      'Request',
    );
    expect(errorArray.length === 1).toEqual(true);

    const otherErrorArray = validateRequest(
      { float: 'Hello' },
      validationSchema,
      'Request',
    );
    expect(otherErrorArray.length === 1).toEqual(true);

    const noErrorsArray = validateRequest(
      { float: '1' },
      validationSchema,
      'Request',
    );
    expect(noErrorsArray.length === 0).toEqual(true);
    const noErrorsArrayAgain = validateRequest(
      { int: 1 },
      validationSchema,
      'Request',
    );
    expect(noErrorsArrayAgain.length === 0).toEqual(true);
  });

  it('Should validate required fields passed within objects', () => {
    const errorArray = validateRequest(
      { requiredInput: {} },
      complexSchema,
      'Request',
    );
    expect(errorArray.length === 1).toEqual(true);
    const otherErrorArray = validateRequest(
      { requiredInput: { someId: uuid() } },
      complexSchema,
      'Request',
    );
    expect(otherErrorArray.length === 0).toEqual(true);
  });

  it('Should validate strings inside arrays', () => {
    const errorArray = validateRequest(
      {
        requiredArray: [{ someId: uuid() }],
        requiredArrayOfStrings: ['Hey'],
      },
      arraySchema,
      'Request',
    );
    expect(errorArray.length === 0).toEqual(true);
    const otherErrorArray = validateRequest(
      {
        requiredArray: [{ someId: uuid() }],
        requiredArrayOfStrings: [1],
      },
      arraySchema,
      'Request',
    );
    expect(otherErrorArray.length === 1).toEqual(true);
  });

  it('Should validate objects inside arrays', () => {
    const errorArray = validateRequest(
      {
        requiredArray: [{}],
        requiredArrayOfStrings: ['Hey'],
      },
      arraySchema,
      'Request',
    );
    expect(errorArray.length === 1).toEqual(true);
    const otherErrorArray = validateRequest(
      {
        requiredArray: [{ someId: uuid() }],
        requiredArrayOfStrings: ['Hey'],
      },
      arraySchema,
      'Request',
    );
    expect(otherErrorArray.length === 0).toEqual(true);
  });
});

const uuid = require('uuid/v4');
const faker = require('faker');
const moment = require('moment');
const { useSequentialIds } = require('./devTools');
const reduceToObject = require('./reduceToObject');
const randomValueFromArray = require('./randomValueFromArray');

const mockIndividualKey = (type, title = '', arrayIndex) => {
  const adjustedTitle = `${title}`.toLowerCase();
  if (type === 'string') {
    if (adjustedTitle.includes('email')) {
      return faker.internet.email();
    }
    if (adjustedTitle.includes('firstname')) {
      return faker.name.firstName();
    }
    if (
      adjustedTitle.includes('lastname') ||
      adjustedTitle.includes('surname')
    ) {
      return faker.name.lastName();
    }
    if (adjustedTitle.includes('lastupdatedby')) {
      return faker.name.findName();
    }
    if (adjustedTitle.includes('date')) {
      return moment(faker.date.future()).format('YYYY-MM-DD');
    }
    if (
      adjustedTitle.includes('pin') ||
      adjustedTitle.includes('cdsid') ||
      adjustedTitle.includes('dslid') ||
      adjustedTitle.includes('cicode')
    ) {
      return `${faker.random.number()}`;
    }
    if (adjustedTitle.includes('market') || adjustedTitle.includes('region')) {
      return faker.address.country();
    }

    return `string: ${faker.name.findName()}`;
  }

  if (type === 'number') {
    return faker.random.number();
  }

  if (type === 'integer') {
    return faker.random.number();
  }

  if (type === 'id') {
    if (arrayIndex && useSequentialIds) return arrayIndex;
    return useSequentialIds ? randomValueFromArray([1, 2]) : uuid();
  }

  if (type === 'boolean') {
    return randomValueFromArray([true, false]);
  }

  if (type === 'GRAPHQL_SCALAR') {
    return `scalar: ${adjustedTitle}`;
  }

  throw new Error(`Unknown key type found: ${type}`);
};

const mockAnyType = ({
  object,
  definitions,
  isDefinition = false,
  arrayIndex,
  globalMockObject,
  lastMockMatch,
}) => {
  if (object.type === 'object' && object.properties) {
    const content = {
      ...Object.keys(object.properties)
        .map((key) => {
          return mockAnyType({
            object: object.properties[key],
            definitions,
            arrayIndex,
            globalMockObject,
            lastMockMatch: globalMockObject[object.title],
          });
        })
        .reduce(reduceToObject, {}),
    };
    return isDefinition ? content : { [object.title]: content };
  }

  if (
    object.type === 'string' ||
    object.type === 'number' ||
    object.type === 'integer' ||
    object.type === 'id' ||
    object.type === 'boolean' ||
    object.type === 'GRAPHQL_SCALAR'
  ) {
    if (
      lastMockMatch &&
      lastMockMatch[object.title] &&
      typeof lastMockMatch[object.title] === 'function'
    ) {
      return { [object.title]: lastMockMatch[object.title](arrayIndex || 0) };
    }
    return {
      [object.title]: mockIndividualKey(object.type, object.title, arrayIndex),
    };
  }

  if (object.constructor === Object && object.type && object.type.type) {
    return mockIndividualKey(object.type.type, undefined, arrayIndex);
  }

  if (object.type === 'array' && object.items) {
    return {
      [object.title]: [
        mockAnyType({
          object: object.items,
          definitions,
          arrayIndex: 0,
          globalMockObject,
          lastMockMatch,
        }),
        mockAnyType({
          object: object.items,
          definitions,
          arrayIndex: 1,
          globalMockObject,
          lastMockMatch,
        }),
      ],
    };
  }

  if (object.type === 'GRAPHQL_ENUM' && object.enum && object.enum.length) {
    /** This mocks enums to return based on their number */
    return randomValueFromArray(object.enum.map((_, index) => index + 1));
  }

  if (object.type && object.type.$ref) {
    const definition = object.type.$ref.replace(/#\/definitions\//, '');
    if (definitions[definition]) {
      return mockAnyType({
        object: definitions[definition],
        definitions,
        isDefinition: true,
        arrayIndex,
        globalMockObject,
        lastMockMatch,
      });
    }
  }

  if (object.$ref) {
    const definition = object.$ref.replace(/#\/definitions\//, '');
    if (definitions[definition]) {
      return mockAnyType({
        object: definitions[definition],
        definitions,
        isDefinition: true,
        arrayIndex,
        globalMockObject,
        lastMockMatch,
      });
    }
  }

  if (object.allOf) {
    const adjustedObject = object.allOf.reduce((a, b) => ({ ...a, ...b }), {});

    return {
      [adjustedObject.title]: mockAnyType({
        object: adjustedObject,
        definitions,
        arrayIndex,
        globalMockObject,
        lastMockMatch,
      }),
    };
  }

  throw new Error(
    `Unknown type of object encountered:\n${JSON.stringify(object, null, 2)}`,
  );
};

module.exports = (definitions = {}, globalMockObject = {}) => {
  return Object.keys(definitions)
    .map((key) => ({
      [key]: mockAnyType({
        object: definitions[key],
        definitions,
        isDefinition: true,
        globalMockObject,
      }),
    }))
    .reduce(reduceToObject, {});
};

