#!/usr/bin/env node

const program = require('commander');
const gaze = require('gaze');
const path = require('path');
const startServer = require('../server');
const { version } = require('../package.json');

program.version(version);

program
  .command('start <contracts>')
  .option('-t, --types <folder>')
  .option('-m, --mocks <folder>')
  .option('-p, --port <port>')
  .action((contractsDir, cmd) => {
    const mocksDir = cmd.mocks;
    const typesDir = cmd.types;
    const port = cmd.port || 4000;
    gaze(
      [
        `${path.resolve(contractsDir)}/**/*.graphql`,
        ...(mocksDir ? [`${path.resolve(mocksDir)}/**/*.js`] : []),
        ...(typesDir ? [`${path.resolve(typesDir)}/**/*.graphql`] : []),
      ],
      (err, watcher) => {
        if (err) throw new Error(err);

        let server = startServer({ port, contractsDir, mocksDir, typesDir });

        watcher.on('all', () => {
          console.log('Change detected...'); // eslint-disable-line
          server.close();
          server = startServer({ port, contractsDir, mocksDir, typesDir });
        });
      },
    );
  });

program.parse(process.argv);

const { parse } = require('graphql/language');
const transform = require('./transform.js');

module.exports = (schema) => {
  if (typeof schema !== 'string') {
    throw new TypeError('GraphQL Schema must be a string');
  }
  return transform(parse(schema));
};

const fs = require('fs');
const file = require('file');
const path = require('path');
const transform = require('../graphql-json-schema');

module.exports = (contractPath, typesDir) => {
  const schemaArray = [fs.readFileSync(contractPath).toString()];

  const types = [];

  if (typesDir) {
    file.walkSync(typesDir, (dir, dirs, files) => {
      files.forEach((fileName) => {
        const contents = fs
          .readFileSync(path.resolve(dir, fileName))
          .toString();
        types.push(contents);
      });
    });
  }

  return transform([...types, ...schemaArray].join('\n'));
};

module.exports = {
  /**
   * Enable this to make ids coerce to either 1 or 2.
   * This is handy for when you want to check if a select
   * box is filling based on config information passed down.
   *
   * But it's less handy if you need every id on a page to be unique,
   * which is true for most cases. By default, this should be false
   */
  useSequentialIds: false,
};

const express = require('express');
const path = require('path');
const fs = require('fs');
const bodyParser = require('body-parser');
const validateRequest = require('./validateRequest');
const getSchema = require('./getSchema');
const generateMocks = require('./generateMocks');

const startServer = ({ contractsDir, mocksDir, typesDir, port = 4000 }) => {
  const app = express();
  app.use(bodyParser.json({ limit: '999mb', type: `application/json` }));

  app.use((req, res, next) => {
    res.header('Access-Control-Allow-Origin', '*');
    res.header(
      'Access-Control-Allow-Headers',
      'Origin, X-Requested-With, Content-Type, Accept, Authorization',
    );
    next();
  });

  app.all('*', (req, res) => {
    if (req.method === 'OPTIONS') {
      res.sendStatus(200);
      return;
    }

    const contractPath = `${path.resolve(
      contractsDir,
      req.params[0].replace(/\//, ''),
    )}.graphql`;

    if (fs.existsSync(contractPath)) {
      let mockSchema = {};

      if (mocksDir) {
        const mockSchemaPath = path.resolve(
          mocksDir,
          `${req.params[0].replace(/\//, '')}.js`,
        );
        const mockSchemaExists = fs.existsSync(mockSchemaPath);

        if (mockSchemaExists) {
          mockSchema = module.require(mockSchemaPath);
        }
      }

      const schema = getSchema(contractPath, typesDir);

      try {
        const mocks = generateMocks(schema.definitions, mockSchema);

        const request = {
          ...req.body,
          ...req.query,
        };

        let errors = [];

        /** Cannot validate multipart/form-data at present */
        // eslint-disable-next-line no-underscore-dangle
        if (!request._ignoreExcess && !req.is('multipart/form-data')) {
          errors = validateRequest(request, schema, 'Request');
        }

        setTimeout(() => {
          if (errors.length > 0) {
            res.status(200);
            res.json({
              Errors: errors.map((Description) => {
                return { Description };
              }),
            });
          } else {
            res.status(200);
            res.json(mocks.Response);
          }
        }, 200);
      } catch (e) {
        res.json({
          Errors: [
            {
              Description: e.toString(),
            },
          ],
        });
      }

      return;
    }

    res.status(404);
    res.send('');
  });

  const server = app.listen(port, () =>
    // eslint-disable-next-line no-console
    console.log(`Started server on port ${port}...`),
  );
  return server;
};

module.exports = startServer;
